// Original routing client -> real accepted PSRPC handler context -> original
// EgressClient. This is a controlled handler, not full original RoomManager.
package main
import("bufio";"context";"encoding/json";"fmt";"os";"sync";"time";"github.com/livekit/livekit-server/pkg/config";"github.com/livekit/livekit-server/pkg/routing";pb "github.com/livekit/protocol/livekit";"github.com/livekit/protocol/rpc";"github.com/livekit/protocol/logger";"github.com/livekit/psrpc";"google.golang.org/protobuf/proto")
type row struct{Sent int64 `json:"sent_ns"`;Expiry int64 `json:"expiry_ns"`}
type observedBus struct{psrpc.MessageBus;mu sync.Mutex;rows []row}
func(b *observedBus)Publish(ctx context.Context,c psrpc.Channel,m proto.Message)error{p:=m.ProtoReflect();f:=p.Descriptor().Fields();sent,expiry:=f.ByName("sent_at"),f.ByName("expiry");if sent!=nil&&expiry!=nil{b.mu.Lock();b.rows=append(b.rows,row{p.Get(sent).Int(),p.Get(expiry).Int()});b.mu.Unlock()};return b.MessageBus.Publish(ctx,c,m)}
type input struct{ID string `json:"id"`;Attempts int `json:"attempts"`;Timeout string `json:"timeout"`;WorkerAttempts int `json:"worker_attempts"`}
type service struct{egress rpc.EgressClient;mu sync.Mutex;deadlines []int64;active int}
func(s *service)CreateRoom(ctx context.Context,r *pb.CreateRoomRequest)(*pb.Room,error){d,_:=ctx.Deadline();s.mu.Lock();s.active++;s.deadlines=append(s.deadlines,d.UnixNano());s.mu.Unlock();defer func(){s.mu.Lock();s.active--;s.mu.Unlock()}();_,e:=s.egress.StartEgress(ctx,"",&rpc.StartEgressRequest{EgressId:"EG_owned",RoomId:"RM_owned",Request:&rpc.StartEgressRequest_RoomComposite{RoomComposite:&pb.RoomCompositeEgressRequest{RoomName:r.Name,AudioOnly:true}}});return nil,e}
func main(){f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};defer f.Close();out:=json.NewEncoder(os.Stdout);scan:=bufio.NewScanner(f);for scan.Scan(){var c input;if e=json.Unmarshal(scan.Bytes(),&c);e!=nil{panic(e)};cfg,e:=config.NewConfig(fmt.Sprintf("rtc: {node_ip: 127.0.0.1, use_external_ip: false}\nroom: {create_room_attempts: %d, create_room_timeout: %s}\n",c.Attempts,c.Timeout),true,nil,nil);if e!=nil{panic(e)};b:=&observedBus{MessageBus:psrpc.NewLocalMessageBus(),rows:[]row{}};ec,e:=rpc.NewEgressClient(rpc.ClientParams{Observer:rpc.UnimplementedMetricsObserver{},Bus:b,Logger:logger.GetDiscardLogger(),PSRPCConfig:rpc.PSRPCConfig{MaxAttempts:c.WorkerAttempts,Timeout:3*time.Second,Backoff:2*time.Second,BufferSize:100}});if e!=nil{panic(e)};svc:=&service{egress:ec,deadlines:[]int64{}};server,e:=rpc.NewTypedRoomManagerServer(svc,b);if e!=nil{panic(e)};if e=server.RegisterCreateRoomTopic(pb.NodeID("ND_owner"));e!=nil{panic(e)};client,e:=routing.NewRoomManagerClient(rpc.ClientParams{Observer:rpc.UnimplementedMetricsObserver{},Bus:b,Logger:logger.GetDiscardLogger(),PSRPCConfig:rpc.PSRPCConfig{BufferSize:100}},cfg.Room);if e!=nil{panic(e)};ctx,cancel:=context.WithTimeout(context.Background(),20*time.Second);_,err:=client.CreateRoom(ctx,pb.NodeID("ND_owner"),&pb.CreateRoomRequest{Name:"owned-deadline"});cancel();client.Close();server.Shutdown();ec.Close();b.mu.Lock();rows:=append([]row{},b.rows...);b.mu.Unlock();svc.mu.Lock();deadlines:=append([]int64{},svc.deadlines...);active:=svc.active;svc.mu.Unlock();code,text:="","";if err!=nil{text=err.Error();if v,ok:=psrpc.GetErrorCode(err);ok{code=string(v)}};if e=out.Encode(map[string]any{"id":c.ID,"request_wire":rows,"accepted_context_deadlines_ns":deadlines,"active_after_shutdown":active,"error_code":code,"error":text});e!=nil{panic(e)}};if e=scan.Err();e!=nil{panic(e)}}
